insert into public.reviews (id, restaurant_id, author, reviewer_tolerance, safety_rating, taste_rating, text, date, sample) values
('rev_seed_1','r01','Sam','celiac',5,4,'Whole menu is GF so I could relax and just order. Crust was great.','2026-10-20'::date,true),
('rev_seed_2','r01','Jo','preference',null,5,'Best pizza I have had, GF or not.','2026-09-30'::date,true),
('rev_seed_3','r02','Priya','sensitive',4,5,'Corn tacos were excellent. Staff checked on the chips fryer when I asked.','2026-09-10'::date,true),
('rev_seed_4','r03','Dana','celiac',2,4,'Great fish, but they were unsure about the miso and the soy. I stuck to sashimi.','2026-07-30'::date,true),
('rev_seed_5','r05','Lee','celiac',5,5,'They brought the GF pasta in a separate pot without me asking twice.','2026-10-30'::date,true),
('rev_seed_6','r05','Maya P.','preference',null,5,'The GF cacio e pepe is the real thing. Date-night worthy.','2026-10-02'::date,true),
('rev_seed_7','r06','Chris','sensitive',3,4,'Lettuce-wrap burger was good. Fries are shared fryer, so I skipped them.','2026-09-25'::date,true),
('rev_seed_8','r07','Anika','sensitive',4,5,'Most of the menu works. Confirm the dal has no hing with wheat.','2026-09-18'::date,true),
('rev_seed_9','r11','Rae','celiac',4,4,'Staff knew the question before I finished asking. Bowls are a little bland.','2026-11-05'::date,true),
('rev_seed_10','r15','Tom','celiac',5,4,'I cried a little at the cinnamon bun. Whole shop is GF.','2026-11-08'::date,true),
('rev_seed_11','r16','Jess','preference',null,3,'GF beer on tap is a nice touch. Food is fine.','2026-08-29'::date,true),
('rev_seed_12','r17','Kim','celiac',2,4,'Pho was tasty but staff were not sure about the hoisin or the noodles. I felt off after.','2026-03-10'::date,true),
('rev_seed_13','r18','Noor','sensitive',5,5,'Dedicated fryer, vegan and fun. My new Friday spot.','2026-10-09'::date,true),
('rev_seed_14','r19','Ben','celiac',4,4,'Raw bar is simple and safe-feeling. Staff were careful with the fried items.','2026-10-15'::date,true);
